77	/// `POST /agent/identity/claim` — start or resume a claim ceremony (no auth; the `claim_token` is
78	/// the credential).
79	pub async fn post_agent_claim(
80	    State(state): State<AppState>,
81	    Json(req): Json<ClaimInitiateRequest>,
82	) -> Response {
83	    match initiate(&state, &req).await {
84	        Ok(response) => response,
85	        Err(err) => err.into_response(),
86	    }
87	}
