89	async fn initiate(
90	    state: &AppState,
91	    req: &ClaimInitiateRequest,
92	) -> Result<Response, AgentAuthError> {
93	    let claim_token = req
94	        .claim_token
95	        .as_deref()
96	        .filter(|s| !s.is_empty())
97	        .ok_or_else(|| {
98	            AgentAuthError::new(
99	                StatusCode::BAD_REQUEST,
100	                "invalid_request",
101	                "missing required field: claim_token",
102	            )
103	        })?;
104	
105	    let identity = get_agent_identity_by_claim_token(&state.db, claim_token)
106	        .await?
107	        .ok_or_else(|| {
108	            AgentAuthError::new(
109	                StatusCode::BAD_REQUEST,
110	                "invalid_claim_token",
111	                "the claim token is unknown",
112	            )
113	        })?;
114	
115	    match identity.status {
116	        AgentIdentityStatus::Claimed => {
117	            return Err(AgentAuthError::new(
118	                StatusCode::BAD_REQUEST,
119	                "claimed_or_in_flight",
120	                "this registration has already been claimed",
121	            ));
122	        }
123	        // A revoked identity is not distinguished from an unknown token (don't leak state).
124	        AgentIdentityStatus::Revoked => {
125	            return Err(AgentAuthError::new(
126	                StatusCode::BAD_REQUEST,
127	                "invalid_claim_token",
128	                "the claim token is unknown",
129	            ));
130	        }
131	        AgentIdentityStatus::Active => {}
132	    }
133	
134	    // The claim token has its own TTL (the auth.md pre-claim window). Its stored expiry uses the
135	    // sqlite `YYYY-MM-DD HH:MM:SS` format, which sorts chronologically, so a lexicographic compare
136	    // against "now" in the same format is a correct expiry check.
137	    let now_sqlite = to_sqlite_datetime(&Utc::now());
138	    if identity
139	        .claim_token_expires_at
140	        .as_deref()
141	        .map(|exp| exp <= now_sqlite.as_str())
142	        .unwrap_or(false)
143	    {
144	        return Err(AgentAuthError::new(
145	            StatusCode::BAD_REQUEST,
146	            "claim_expired",
147	            "the claim token has expired; re-register",
148	        ));
149	    }
150	
151	    // Resume an in-flight ceremony rather than minting a second user_code: an agent that lost the
152	    // response, or is polling, gets the same code back. Otherwise open a fresh attempt.
153	    let (attempt_id, user_code, expiry) =
154	        match latest_agent_claim_attempt_for_identity(&state.db, &identity.id).await? {
155	            Some(attempt) if attempt.is_pending() => (
156	                attempt.id,
157	                attempt.user_code,
158	                parse_sqlite_datetime(&attempt.user_code_expires_at),
159	            ),
160	            _ => {
161	                let attempt_id = new_claim_attempt_id();
162	                let user_code = generate_code();
163	                let expiry = Utc::now()
164	                    + Duration::seconds(state.config.agent_auth.user_code_ttl_secs as i64);
165	                insert_agent_claim_attempt(
166	                    &state.db,
167	                    &NewAgentClaimAttempt {
168	                        id: &attempt_id,
169	                        identity_id: &identity.id,
170	                        user_code: &user_code,
171	                        user_code_expires_at: &to_sqlite_datetime(&expiry),
172	                        email: req.email.as_deref().or(identity.email.as_deref()),
173	                    },
174	                )
175	                .await?;
176	                (attempt_id, user_code, expiry)
177	            }
178	        };
179	
180	    let expires_in = (expiry - Utc::now()).num_seconds().max(0);
181	    let body = ClaimInitiateResponse {
182	        registration_id: identity.id,
183	        claim_attempt_id: attempt_id,
184	        status: "initiated",
185	        expires_at: expiry.to_rfc3339_opts(SecondsFormat::Millis, true),
186	        claim_attempt: ClaimAttemptBlock {
187	            user_code,
188	            expires_in,
189	            verification_uri: verification_uri(&state.config.agent_auth, &state.config.public_url),
190	            interval: POLL_INTERVAL_SECS,
191	        },
192	    };
193	    Ok((StatusCode::OK, Json(body)).into_response())
194	}
