213	/// `POST /agent/identity/claim/confirm` — the account owner confirms a claim (full-access authed).
214	pub async fn post_agent_claim_confirm(
215	    user: AuthenticatedUser,
216	    State(state): State<AppState>,
217	    Json(req): Json<ClaimConfirmRequest>,
218	) -> Response {
219	    match confirm(user, &state, &req).await {
220	        Ok(response) => response,
221	        Err(err) => err.into_response(),
222	    }
223	}
224	
225	async fn confirm(
226	    user: AuthenticatedUser,
227	    state: &AppState,
228	    req: &ClaimConfirmRequest,
229	) -> Result<Response, AgentAuthError> {
230	    // Only the account holder's own full-access credential may confirm. App-password tokens
231	    // (narrower scope) are refused by the scope check; agent-derived tokens map to `Access` for
232	    // coarse admission, so `is_agent` closes the gap — an agent must never confirm itself.
233	    if user.scope != AuthScope::Access {
234	        return Err(AgentAuthError::new(
235	            StatusCode::UNAUTHORIZED,
236	            "invalid_token",
237	            "a full-access token is required to confirm an agent claim",
238	        ));
239	    }
240	    if user.is_agent() {
241	        return Err(AgentAuthError::new(
242	            StatusCode::FORBIDDEN,
243	            "access_denied",
244	            "agent-derived credentials cannot confirm a claim",
245	        ));
246	    }
247	
248	    let user_code = req
249	        .user_code
250	        .as_deref()
251	        .filter(|s| !s.is_empty())
252	        .ok_or_else(|| {
253	            AgentAuthError::new(
254	                StatusCode::BAD_REQUEST,
255	                "invalid_request",
256	                "missing required field: user_code",
257	            )
258	        })?;
259	
260	    // Brute-forcing the `user_code` is bounded today by the global per-IP rate limiter, and this
261	    // endpoint is already full-access authenticated — so the guessing surface is an *authenticated*
262	    // caller racing a ~36^6-wide code within its short TTL (and success only lets them bind an
263	    // ownerless anonymous registration to their own account, not take over a victim's). A dedicated
264	    // per-code failure lockout is intentionally left to the follow-on wallet agent-consent/audit
265	    // hardening work, which owns claim rate-limiting — consistent with the sibling short-code
266	    // surface `/v1/transfer/accept`, which likewise relies on the shared limiter.
267	    let attempt = get_agent_claim_attempt_by_user_code(&state.db, user_code)
268	        .await?
269	        .ok_or_else(|| {
270	            AgentAuthError::new(
271	                StatusCode::BAD_REQUEST,
272	                "invalid_user_code",
273	                "the user code is unknown",
274	            )
275	        })?;
276	    if !attempt.is_pending() {
277	        // An already-consumed attempt is `claimed_or_in_flight`; anything else non-pending (swept
278	        // expired, or pending-but-past-expiry) is a lapsed code.
279	        return Err(if attempt.status == ClaimAttemptStatus::Completed {
280	            AgentAuthError::new(
281	                StatusCode::BAD_REQUEST,
282	                "claimed_or_in_flight",
283	                "this user code has already been used",
284	            )
285	        } else {
286	            AgentAuthError::new(
287	                StatusCode::BAD_REQUEST,
288	                "claim_expired",
289	                "the user code has expired; restart the claim",
290	            )
291	        });
292	    }
293	
294	    let identity = get_agent_identity(&state.db, &attempt.identity_id)
295	        .await?
296	        .ok_or_else(AgentAuthError::server_error)?;
297	
298	    if let Some(req_reg) = req.registration_id.as_deref().filter(|s| !s.is_empty()) {
299	        if req_reg != identity.id {
300	            return Err(AgentAuthError::new(
301	                StatusCode::BAD_REQUEST,
302	                "invalid_request",
303	                "registration_id does not match this user code",
304	            ));
305	        }
306	    }
307	
308	    match identity.status {
309	        AgentIdentityStatus::Claimed => {
310	            return Err(AgentAuthError::new(
311	                StatusCode::BAD_REQUEST,
312	                "claimed_or_in_flight",
313	                "this registration has already been claimed",
314	            ));
315	        }
316	        AgentIdentityStatus::Revoked => {
317	            return Err(AgentAuthError::new(
318	                StatusCode::FORBIDDEN,
319	                "access_denied",
320	                "this agent identity has been revoked",
321	            ));
322	        }
323	        AgentIdentityStatus::Active => {}
324	    }
325	
326	    // Authorization. A registration already bound to an owner (service_auth / identity_assertion)
327	    // may be confirmed only by that owner. An ownerless anonymous registration is bound to whoever
328	    // completes the ceremony — the `user_code` they were shown is the authorization.
329	    let bind_did = match identity.did.as_deref() {
330	        Some(bound) => {
331	            if bound != user.did {
332	                return Err(AgentAuthError::new(
333	                    StatusCode::FORBIDDEN,
334	                    "access_denied",
335	                    "this claim is bound to a different account",
336	                ));
337	            }
338	            None
339	        }
340	        None => Some(user.did.as_str()),
341	    };
342	
343	    // The post-claim assertion carries the operator's current full granted-scope profile. Normalize
344	    // it into a deterministic, deduplicated set so this mint matches the `identity_assertion` mint
345	    // path byte-for-byte: `intersect_scope_tokens(xs, xs)` is the crate's canonicalizer — it returns
346	    // the tokens of `xs` sorted and deduped (a self-intersection, since every token is in both
347	    // operands). There is no separate infallible canonicalizer helper; `canonicalize_agent_scopes`
348	    // is the fallible startup validator, not this hot path.
349	    let granted = &state.config.agent_auth.granted_scopes;
350	    let scopes = intersect_scope_tokens(granted, granted);
351	    let minted = mint_identity_assertion(
352	        &state.oauth_signing_keypair,
353	        &state.config.public_url,
354	        state.config.agent_auth.assertion_ttl_secs,
355	        &user.did,
356	        &identity.id,
357	        identity.registration_type.as_str(),
358	        &scopes,
359	    )?;
360	    let scopes_json = scopes_to_json(&scopes);
361	
362	    // One transaction: consume the pending attempt, then claim the identity. Each write carries its
363	    // own guard (`status = 'pending'` / `status = 'active'`), so a lost race rolls back cleanly
364	    // rather than double-claiming. Every read (and the pure mint) ran before `begin()` — the
365	    // single-connection pool cannot serve a `&SqlitePool` read while a transaction holds the
366	    // connection.
367	    let mut tx = state.db.begin().await.map_err(|e| {
368	        tracing::error!(error = %e, "failed to open transaction for agent claim confirm");
369	        AgentAuthError::server_error()
370	    })?;
371	    if !complete_agent_claim_attempt(&mut *tx, &attempt.id).await? {
372	        return Err(AgentAuthError::new(
373	            StatusCode::CONFLICT,
374	            "claimed_or_in_flight",
375	            "this claim attempt is no longer pending",
376	        ));
377	    }
378	    if !claim_agent_identity(
379	        &mut *tx,
380	        &identity.id,
381	        bind_did,
382	        &scopes_json,
383	        &minted.jwt,
384	        &minted.expires_sqlite,
385	    )
386	    .await?
387	    {
388	        return Err(AgentAuthError::new(
389	            StatusCode::CONFLICT,
390	            "claimed_or_in_flight",
391	            "this registration is no longer active",
392	        ));
393	    }
394	    tx.commit().await.map_err(|e| {
395	        tracing::error!(error = %e, "failed to commit agent claim confirm");
396	        AgentAuthError::server_error()
397	    })?;
398	
399	    Ok((
400	        StatusCode::OK,
401	        Json(ClaimConfirmResponse {
402	            registration_id: identity.id,
403	            status: "claimed",
404	            did: user.did,
405	        }),
406	    )
407	        .into_response())
408	}
