654	    // Prune stale nonces and expired tokens on every request, matching the other grant handlers.
655	    cleanup_expired_state(state).await;
656	
657	    let assertion = match form.assertion.as_deref() {
658	        Some(a) if !a.is_empty() => a,
659	        _ => {
660	            return OAuthTokenError::new("invalid_request", "missing parameter: assertion")
661	                .into_response();
662	        }
663	    };
664	
665	    // RFC 8707: `resource` pins the token to a protected resource. ezpds is the sole resource it
666	    // serves (issuer == resource == public origin), so any other value is an unknown target.
667	    if let Some(resource) = form.resource.as_deref().filter(|r| !r.is_empty()) {
668	        let origin = state.config.public_url.trim_end_matches('/');
669	        if resource.trim_end_matches('/') != origin {
670	            return OAuthTokenError::new("invalid_target", "resource must be this server's origin")
671	                .into_response();
672	        }
673	    }
674	
675	    let claims = match verify_agent_assertion(assertion, state) {
676	        Ok(claims) => claims,
677	        Err(e) => return e.into_response(),
678	    };
679	
680	    // State gate (the assertion stays cryptographically valid until it expires, so identity state
681	    // is enforced here at exchange time, per RFC 7523 §3.1). Require exactly `Claimed`: that is the
682	    // only state for which the registration flow mints a service-signed assertion. A `Revoked`
683	    // identity was turned off by its owner/operator — an explicit `access_denied` closes the
684	    // credential. `Active` still owes the claim ceremony, and a missing/mismatched row can't be
685	    // trusted, so both → `invalid_grant`. Also require the stored
686	    // DID to match the assertion's `sub`, so the state lookup and the token subject resolve to the
687	    // same identity even if the issuance path ever drifts.
688	    match get_agent_identity(&state.db, &claims.registration_id).await {
689	        Ok(Some(identity))
690	            if identity.status == AgentIdentityStatus::Claimed
691	                && identity.did.as_deref() == Some(claims.sub.as_str()) => {}
