693	            return OAuthTokenError::new("access_denied", "the agent identity has been revoked")
694	                .into_response();
695	        }
696	        Ok(_) => {
697	            return OAuthTokenError::new("invalid_grant", "the agent identity is not claimed")
698	                .into_response();
699	        }
700	        Err(e) => {
701	            tracing::error!(error = %e, "failed to load agent identity for jwt-bearer exchange");
