107	/// Claims of a service-signed `identity_assertion` — the token the confirmed agent later exchanges
108	/// at the token endpoint (jwt-bearer grant). Signed with the server's ES256 OAuth key.
109	#[derive(Debug, Serialize)]
110	struct ServiceAssertionClaims {
111	    iss: String,
112	    sub: String,
113	    aud: String,
114	    iat: u64,
115	    exp: u64,
116	    jti: String,
117	    scope: String,
118	    registration_id: String,
119	    registration_type: &'static str,
120	}
