122	/// Mint a service-signed `identity_assertion` bound to `subject` (the account DID once claimed, or
123	/// the registration id for a pre-claim anonymous assertion), carrying the granted `scopes` and the
124	/// registration's id/type. Signed with the server's ES256 OAuth key.
125	pub(crate) fn mint_identity_assertion(
126	    keypair: &OAuthSigningKey,
127	    public_url: &str,
128	    ttl_secs: u64,
129	    subject: &str,
130	    registration_id: &str,
131	    registration_type: &'static str,
132	    scopes: &[String],
133	) -> Result<MintedAssertion, AgentAuthError> {
134	    let issued = Utc::now();
135	    let expires = issued + Duration::seconds(ttl_secs as i64);
136	    let base = public_url.trim_end_matches('/').to_string();
137	
138	    let claims = ServiceAssertionClaims {
139	        iss: base.clone(),
140	        sub: subject.to_string(),
141	        aud: base,
142	        iat: issued.timestamp().max(0) as u64,
143	        exp: expires.timestamp().max(0) as u64,
144	        jti: Uuid::new_v4().to_string(),
145	        scope: scopes.join(" "),
146	        registration_id: registration_id.to_string(),
147	        registration_type,
148	    };
149	
150	    let mut header = jsonwebtoken::Header::new(Algorithm::ES256);
151	    header.kid = Some(keypair.key_id.clone());
152	    let jwt = jsonwebtoken::encode(&header, &claims, &keypair.encoding_key).map_err(|e| {
153	        tracing::error!(error = %e, "failed to sign agent identity assertion");
154	        AgentAuthError::server_error()
155	    })?;
156	
157	    Ok(MintedAssertion {
158	        jwt,
159	        expires_sqlite: to_sqlite_datetime(&expires),
160	        expires_rfc3339: expires.to_rfc3339_opts(SecondsFormat::Millis, true),
161	    })
162	}
