740	/// Verify a service-signed `identity_assertion`: ES256 signature under this server's own OAuth key
741	/// (the assertion is self-signed), plus `iss`/`aud` == this server's origin and an unexpired `exp`.
742	/// Any failure — bad signature, wrong issuer/audience, expired, or a malformed/foreign token —
743	/// maps to `invalid_grant` (RFC 7523 §3.1).
744	fn verify_agent_assertion(
745	    assertion: &str,
746	    state: &AppState,
747	) -> Result<AgentAssertionClaims, OAuthTokenError> {
748	    // Reuse the shared loader — the assertion is signed by the same OAuth key as access tokens.
749	    let decoding_key = crate::auth::jwt::oauth_es256_decoding_key(state)
750	        .map_err(|_| OAuthTokenError::new("server_error", "assertion verification unavailable"))?;
751	
752	    let origin = state.config.public_url.trim_end_matches('/');
753	    let mut validation = jsonwebtoken::Validation::new(jsonwebtoken::Algorithm::ES256);
754	    validation.set_issuer(&[origin]);
755	    validation.set_audience(&[origin]);
756	    validation.set_required_spec_claims(&["exp", "sub", "iss", "aud"]);
757	    validation.leeway = 0;
758	
759	    jsonwebtoken::decode::<AgentAssertionClaims>(assertion, &decoding_key, &validation)
760	        .map(|data| data.claims)
761	        .map_err(|e| {
762	            tracing::debug!(error = %e, error_kind = ?e.kind(), "agent identity_assertion verification failed");
763	            OAuthTokenError::new("invalid_grant", "assertion is invalid, expired, or not for this server")
764	        })
765	}
